import React, { useState, useRef } from 'react';    
import { Button } from 'primereact/button';
import { Toast } from 'primereact/toast';
import { Avatar } from 'primereact/avatar';

export default function Template() {
    const [visible, setVisible] = useState(false);
    const toastBC = useRef(null);

    const clear = () => {
        toastBC.current.clear();
        setVisible(false);
    };

    const confirm = () => {
        if (!visible) {
            setVisible(true);
            toastBC.current.clear();
            toastBC.current.show({
                className: 'success',
                summary: 'Can you send me the report?',
                sticky: true,
                content: (
                    <div className="fxb column fvs" style={{ flex: '1' }}>
                        <div className="fxb fvc gp2">
                            <Avatar image="https://primefaces.org/cdn/primereact/images/avatar/amyelsner.png" shape="circle" />
                            <span className="font-bold wpr">Amy Elsner</span>
                        </div>
                        <div className="font-medium mgy6 wpr">Can you send me the report?</div>
                        <Button label="Reply" className="success" onClick={clear}></Button>
                    </div>
                )
            });
        }
    };

    return (
        <div className="">
            <Toast ref={toastBC} position="bottom-center" onRemove={clear} />
            <Button onClick={confirm} label="Confirm" />
        </div>
    )

}